/* Настройки сборки rlottie под «Ловит» (iOS).
 *
 * Обычно этот файл порождает сборочная система библиотеки; у нас сборка
 * своя, поэтому он написан руками. Всё необязательное выключено — намеренно.
 */

#ifndef LOVIT_RLOTTIE_CONFIG_H
#define LOVIT_RLOTTIE_CONFIG_H

/* Отрисовка в своих потоках не нужна: кадр готовится по требованию, и делает
 * это уже наш собственный поток. Лишние потоки на телефоне — лишняя память и
 * лишний расход батареи. */
/* #define LOTTIE_THREAD_SUPPORT */

/* Запас разобранных сцен внутри библиотеки не нужен: мы и так держим открытый
 * стикер, пока он на экране, а держать больше на этом телефоне негде. */
/* #define LOTTIE_CACHE_SUPPORT */

/* Свой журнал библиотеки выключен: он пишет в отдельный файл своим потоком, а
 * у нас есть собственный журнал. */
/* #define LOTTIE_LOGGING_SUPPORT */

/* Этот признак означает не «уметь картинки», а «подгружать разбор картинок
 * отдельной библиотекой на ходу». В песочнице телефона так нельзя — да и
 * незачем: stb собран прямо внутрь, и разбор доступен без всякой подгрузки. */
/* #define LOTTIE_IMAGE_MODULE_SUPPORT */

#endif
